<span style="align-self:flex-start;height:32px;padding:0 14px 0 10px;border-radius:8px;border:1px solid ${V.olv};background:${V.bg};display:inline-flex;align-items:center;gap:8px"><span style="width:8px;height:8px;border-radius:999px;background:${V.inc}"></span><span style="${tx('label',bp,V.onv,'white-space:nowrap')}">Local-first personal finance, made in India</span></span>
