const statCard = (bp, v, l, o={}) => cardBox(`<div style="${tx('stat',bp,V.p,'font-variant-numeric:tabular-nums')}">${v}</div><div style="margin-top:6px;${tx('small',bp,V.onv,'text-wrap:pretty')}">${l}</div>`, {bg:V.c1, r:24, pad:bp==='m'?20:24, ex:o.ex||''});
const H_numbers = (bp) => { const m = bp==='m', t = bp==='t';
  return sec(bp, wrapC(bp, `${shead(bp,'In numbers','Small app. A lot inside.')}<div style="display:grid;grid-template-columns:${m?'1fr 1fr':t?'repeat(3,minmax(0,1fr))':'repeat(6,minmax(0,1fr))'};gap:${m?12:16}px;margin-top:${m?32:40}px">${NUMS.map(([v,l],i)=>statCard(bp,v,l,{ex:m&&i===4?'grid-column:span 2;':''})).join('')}</div>`)); };
