const relCard = (bp, f) => `<a href="#" style="display:flex;align-items:center;gap:14px;padding:14px 16px;border-radius:16px;background:${V.c1};border:1px solid ${V.olv};text-decoration:none">${tile(f.icon,{s:40})}<div style="flex:1;min-width:0"><div style="${tx('t2',bp,V.on)}">${f.title}</div><div style="margin-top:4px">${badges(f)}</div></div>${ic('chevron_right',20,V.onv)}</a>`;
