  if (m) return `${navBar(bp,'Docs')}<main>${wrapC(bp, `<div style="padding-top:${top(bp)}px;display:flex;flex-direction:column;gap:12px"><button type="button" aria-expanded="false" style="height:48px;padding:0 12px 0 16px;border-radius:16px;background:${V.c2};border:1px solid ${V.olv};display:flex;align-items:center;gap:12px;cursor:pointer;font-family:${F}">${ic('menu_book',20,V.onv)}<span style="flex:1;text-align:left;${tx('label',bp,V.on)}">Docs · Privacy Policy</span>${ic('expand_more',22,V.onv)}</button><button type="button" aria-expanded="false" style="height:48px;padding:0 12px 0 16px;border-radius:16px;background:transparent;border:1px solid ${V.olv};display:flex;align-items:center;gap:12px;cursor:pointer;font-family:${F}">${ic('toc',20,V.onv)}<span style="flex:1;text-align:left;${tx('label',bp,V.on)}">On this page</span>${ic('expand_more',22,V.onv)}</button></div><div style="padding:32px 0 64px">${art}</div>`)}</main>${footer(bp)}${mobFab({icon:1})}`;
